package com.cryptoloan.contract.adapters.out;import com.cryptoloan.contract.domain.port.out.ContractPorts.BlockchainSignature;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.time.Instant;import java.util.HexFormat;import org.springframework.stereotype.Component;@Component class DemoBlockchainSignatureAdapter implements BlockchainSignature{public String sign(Long id,String hash,String signer){try{return"0x"+HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest((id+":"+hash+":"+signer+":"+Instant.now()).getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}}

